// Embedded display fonts (latin subsets, WOFF2), so the game looks the same
// offline and from file://. All three families are under the SIL Open Font
// License 1.1: Cinzel and Cinzel Decorative (c) Natanael Gama; Alegreya
// (c) Juan Pablo del Peral / Huerta Tipografica. If a font fails to load the
// stylesheet falls back to Palatino / Georgia, which also look right.
const FACES = [
  ['Cinzel', '', { weight: '400 900' }],
  ['Cinzel Decorative', '', { weight: '700' }],
  ['Alegreya', '', { weight: '400 900', style: 'italic' }],
  ['Alegreya', '', { weight: '400 900' }],
];

export function loadFonts() {
  if (typeof FontFace === 'undefined' || !document.fonts) return;
  for (const [family, data, desc] of FACES) {
    try {
      const face = new FontFace(family, 'url(data:font/woff2;base64,' + data + ')', { display: 'swap', ...desc });
      document.fonts.add(face);
      face.load().catch(() => { /* the fallbacks will do */ });
    } catch { /* old browser: fallbacks */ }
  }
}
